// LeaderboardManager.cs
using System.Collections.Generic;
using UnityEngine;

public class LeaderboardManager : MonoBehaviour
{
    private List<int> _scores = new List<int>();

    public void AddScore(int newScore)
    {
        _scores.Add(newScore);
        // Bubble sort manual — O(n²)
        for (int i = 0; i < _scores.Count - 1; i++)
        {
            for (int j = 0; j < _scores.Count - 1 - i; j++)
            {
                if (_scores[j] < _scores[j + 1])
                {
                    int temp    = _scores[j];
                    _scores[j]  = _scores[j + 1];
                    _scores[j + 1] = temp;
                }
            }
        }
    }

    public List<int> GetTopScores(int count)
    {
        return _scores.GetRange(0, Mathf.Min(count, _scores.Count));
    }
}

