// LeaderboardManager.cs — SortedList mantiene el orden automáticamente
using System.Collections.Generic;
using UnityEngine;

public class LeaderboardManager : MonoBehaviour
{
    // Clave: score (negativo para orden descendente), Valor: nombre o ID
    // SortedList inserta en O(log n) y siempre queda ordenado
    private SortedList<int, string> _scores = new SortedList<int, string>();
    private int _uniqueKey = 0; // desempate si dos scores son iguales

    public void AddScore(int newScore, string playerName)
    {
        // Se usa clave negativa para que el mayor score quede primero
        // El uniqueKey evita colisión de claves duplicadas
        int key = -newScore * 10000 - _uniqueKey++;
        _scores[key] = playerName;
    }

    public IList<KeyValuePair<int, string>> GetTopScores(int count)
    {
        var result = new List<KeyValuePair<int, string>>();
        int taken  = 0;
        foreach (var pair in _scores)
        {
            if (taken >= count) break;
            // Revertir clave negativa para mostrar el score real
            result.Add(new KeyValuePair<int, string>(-pair.Key / 10000, pair.Value));
            taken++;
        }
        return result;
    }

    // Alternativa simple si solo guardas enteros sin nombre:
    // private List<int> _scores = new List<int>();
    // AddScore: _scores.Add(score); _scores.Sort(); _scores.Reverse();
    // Sort() de .NET usa Introsort — O(n log n) — mucho mejor que O(n²)
}

