using System.Collections.Generic;
using UnityEngine;

public class UndoSystem : MonoBehaviour
{
    private List<PlayerAction> _history = new List<PlayerAction>();

    public void RecordAction(PlayerAction action)
    {
        _history.Add(action);
    }

    // O(n) — RemoveAt desplaza todos los elementos siguientes
    public PlayerAction Undo()
    {
        if (_history.Count == 0) return null;

        int lastIndex   = _history.Count - 1;
        PlayerAction action = _history[lastIndex];
        _history.RemoveAt(lastIndex); // desplaza n elementos
        return action;
    }

    public PlayerAction PeekLastAction()
    {
        if (_history.Count == 0) return null;
        return _history[_history.Count - 1];
    }

    public bool HasHistory => _history.Count > 0;
}

