// UndoSystem.cs — Stack<T> para semántica LIFO con operaciones O(1)
using System.Collections.Generic;
using UnityEngine;

public class UndoSystem : MonoBehaviour
{
    // Stack<T>: Push, Pop y Peek son todos O(1)
    // Semánticamente correcto: ES una pila de deshacer
    private Stack<PlayerAction> _history = new Stack<PlayerAction>();

    public void RecordAction(PlayerAction action)
    {
        _history.Push(action); // O(1)
    }

    // O(1) — no hay desplazamiento de elementos
    public PlayerAction Undo()
    {
        if (_history.Count == 0) return null;
        return _history.Pop(); // elimina y devuelve el tope en O(1)
    }

    // O(1) — solo lee el tope sin modificar la pila
    public PlayerAction PeekLastAction()
    {
        if (_history.Count == 0) return null;
        return _history.Peek();
    }

    public bool HasHistory => _history.Count > 0;

    public void ClearHistory() => _history.Clear();
}

