// TurnManager.cs — Queue<T> para cola FIFO con Enqueue/Dequeue O(1)
using System.Collections.Generic;
using UnityEngine;

public class TurnManager : MonoBehaviour
{
    // Queue<T> usa un buffer circular internamente:
    // Enqueue y Dequeue son O(1) sin desplazamiento de memoria
    private Queue<Unit> _turnQueue = new Queue<Unit>();

    public void EnqueueUnit(Unit unit)
    {
        _turnQueue.Enqueue(unit); // O(1) — agrega al final del buffer
    }

    // O(1) — solo avanza el puntero de inicio del buffer circular
    public Unit GetNextUnit()
    {
        if (_turnQueue.Count == 0) return null;
        return _turnQueue.Dequeue();
    }

    // Ver quién es el siguiente sin sacarlo de la cola
    public Unit PeekNextUnit()
    {
        if (_turnQueue.Count == 0) return null;
        return _turnQueue.Peek(); // O(1)
    }

    // Para re-encolar la unidad al final del turno (turno cíclico)
    public void RequeueUnit(Unit unit)
    {
        _turnQueue.Enqueue(unit);
    }

    public int RemainingUnits => _turnQueue.Count;
}

