using System.Collections.Generic;
using UnityEngine;

public class Inventory : MonoBehaviour
{
    // List para preservar orden de adquisición e iteración UI
    public List<string> items    = new List<string>();
    // HashSet para verificaciones de existencia O(1)
    private HashSet<string> _itemIds = new HashSet<string>();

    public void AddItem(string itemId)
    {
        if (_itemIds.Add(itemId)) // Add devuelve false si ya existe
            items.Add(itemId);
    }

    public void RemoveItem(string itemId)
    {
        if (_itemIds.Remove(itemId))
            items.Remove(itemId);
    }

    // O(1) — hash del string → lookup directo
    public bool HasItem(string itemId) => _itemIds.Contains(itemId);
}

