    {
        if (_currentNode == null) return;
        _currentNode = GetNodeById(_currentNode.NextNodeId); // O(n)
    }

    public void SelectChoice(int choiceIndex)
    {
        if (_currentNode == null) return;
        int targetId = _currentNode.ChoiceNodeIds[choiceIndex];
        _currentNode = GetNodeById(targetId); // O(n)
    }
}

