        // Alternativamente sin LINQ:
        // _nodeMap = new Dictionary<int, DialogueNode>(nodes.Count);
        // foreach (var node in nodes) _nodeMap[node.Id] = node;

        _currentNode = nodes.Count > 0 ? nodes[0] : null;
    }

    // O(1) — hash del ID → directo al nodo en memoria
    public DialogueNode GetNodeById(int id)
    {
        _nodeMap.TryGetValue(id, out DialogueNode node);
        return node;
    }

    public void AdvanceToNext()
    {
        if (_currentNode?.NextNodeId == null) return;
        _currentNode = GetNodeById(_currentNode.NextNodeId); // O(1)
    }

    public void SelectChoice(int choiceIndex)
    {
        if (_currentNode == null ||
            choiceIndex >= _currentNode.ChoiceNodeIds.Length) return;

        int targetId = _currentNode.ChoiceNodeIds[choiceIndex];
        _currentNode = GetNodeById(targetId); // O(1)
    }

