using System.Collections.Generic;
using UnityEngine;

public class SkillTree : MonoBehaviour
{
    private List<Skill> _skills        = new List<Skill>();
    private List<Skill> _learnedSkills = new List<Skill>();

    // O(n²) — para cada prerequisito busca en la lista de aprendidas
    public bool CanUnlock(string skillId)
    {
        Skill target = null;
        foreach (Skill s in _skills) // O(n): busca el skill por ID
        {
            if (s.Id == skillId) { target = s; break; }
        }
        if (target == null) return false;

        foreach (string prereqId in target.PrerequisiteIds)
        {
            bool found = false;
            foreach (Skill learned in _learnedSkills) // O(n): ¿está aprendida?
            {
                if (learned.Id == prereqId) { found = true; break; }
            }
            if (!found) return false;
        }
        return true;
    }

    public void LearnSkill(string skillId)
    {
        foreach (Skill s in _skills)
        {
            if (s.Id == skillId)
            {
                _learnedSkills.Add(s);
                break;
            }
        }
    }
}

