// SkillTree.cs — Dictionary + HashSet para verificaciones O(1)
using System.Collections.Generic;
using UnityEngine;

public class SkillTree : MonoBehaviour
{
    // Lookup de habilidades por ID: O(1)
    private Dictionary<string, Skill> _skills      = new Dictionary<string, Skill>();
    // Verificar si aprendida: O(1)
    private HashSet<string>           _learnedIds  = new HashSet<string>();

    public void LoadSkills(IEnumerable<Skill> allSkills)
    {
        _skills.Clear();
        foreach (Skill s in allSkills)
            _skills[s.Id] = s;
    }

    // O(p) donde p = número de prerequisitos del skill — no n²
    public bool CanUnlock(string skillId)
    {
        if (!_skills.TryGetValue(skillId, out Skill target)) // O(1)
            return false;

        if (_learnedIds.Contains(skillId)) // ya aprendida
            return false;

        foreach (string prereqId in target.PrerequisiteIds)
        {
            if (!_learnedIds.Contains(prereqId)) // O(1) por prerequisito
                return false;
        }
        return true;
    }

    public void LearnSkill(string skillId)
    {
        if (_skills.ContainsKey(skillId)) // O(1)
            _learnedIds.Add(skillId);     // O(1)
    }

    public bool IsLearned(string skillId) => _learnedIds.Contains(skillId); // O(1)

    public Skill GetSkill(string skillId)
    {
        _skills.TryGetValue(skillId, out Skill s);
        return s;
    }
}

