// SpatialGrid.cs — grid de celdas para acceso O(1) a enemigos cercanos
using System.Collections.Generic;
using UnityEngine;

public class SpatialGrid : MonoBehaviour
{
    public static SpatialGrid Instance;

    [SerializeField] private float _cellSize = 10f;

    // Cada celda del grid guarda los enemigos dentro de ella
    private Dictionary<Vector2Int, HashSet<Enemy>> _grid
        = new Dictionary<Vector2Int, HashSet<Enemy>>();

    private void Awake() => Instance = this;

    private Vector2Int WorldToCell(Vector3 worldPos)
    {
        return new Vector2Int(
            Mathf.FloorToInt(worldPos.x / _cellSize),
            Mathf.FloorToInt(worldPos.z / _cellSize)
        );
    }

    public void RegisterEnemy(Enemy enemy)
    {
        Vector2Int cell = WorldToCell(enemy.transform.position);
        if (!_grid.ContainsKey(cell))
            _grid[cell] = new HashSet<Enemy>();
        _grid[cell].Add(enemy);
        enemy.CurrentCell = cell;
    }

    // Los enemigos llaman esto al moverse entre celdas
    public void UpdateEnemyCell(Enemy enemy)
    {
        Vector2Int newCell = WorldToCell(enemy.transform.position);
        if (newCell == enemy.CurrentCell) return; // no cambió de celda

        if (_grid.TryGetValue(enemy.CurrentCell, out var oldSet))
            oldSet.Remove(enemy);

        RegisterEnemy(enemy);
    }

    public void UnregisterEnemy(Enemy enemy)
    {
        if (_grid.TryGetValue(enemy.CurrentCell, out var set))
            set.Remove(enemy);
    }

    // Devuelve solo los enemigos en las celdas que se superponen con el radio
    public List<Enemy> GetEnemiesInRadius(Vector3 center, float radius)
    {
        var result = new List<Enemy>();
        int cellRadius = Mathf.CeilToInt(radius / _cellSize);
        Vector2Int centerCell = WorldToCell(center);

        for (int dx = -cellRadius; dx <= cellRadius; dx++)
        {
            for (int dz = -cellRadius; dz <= cellRadius; dz++)
            {
                var cellPos = new Vector2Int(centerCell.x + dx, centerCell.y + dz);
                if (!_grid.TryGetValue(cellPos, out var enemies)) continue;

                foreach (Enemy e in enemies)
                {
                    if (Vector3.Distance(center, e.transform.position) <= radius)
                        result.Add(e);
                }
            }
        }
        return result;
    }
}

// AOEDamage.cs — solo consulta las celdas relevantes
public class AOEDamage : MonoBehaviour
{
    [SerializeField] private float _radius = 5f;
    [SerializeField] private float _damage = 50f;

    public void Explode(Vector3 center)
    {
        // En lugar de 100+ enemigos, solo revisa los de celdas adyacentes
        List<Enemy> nearby = SpatialGrid.Instance.GetEnemiesInRadius(center, _radius);
        foreach (Enemy e in nearby)
            e.TakeDamage(_damage);
    }
}

