using System.Collections.Generic;
using System.Linq;
using UnityEngine;

public class AIScheduler : MonoBehaviour
{
    public static AIScheduler Instance;
    private List<AIAction> _pendingActions = new List<AIAction>();

    private void Awake() => Instance = this;

    public void ScheduleAction(AIAction action)
    {
        _pendingActions.Add(action);
    }

    // O(n log n) + allocación de LINQ — se llama 20 veces por frame
    public AIAction GetHighestPriority()
    {
        if (_pendingActions.Count == 0) return null;

        // OrderByDescending crea un IOrderedEnumerable — allocación en heap
        return _pendingActions
            .OrderByDescending(a => a.priority)
            .First();
    }

    public void RemoveAction(AIAction action)
    {
        _pendingActions.Remove(action);
    }
}

