// AIActionComparer.cs — ordena de mayor a menor prioridad
using System.Collections.Generic;

public class AIActionComparer : IComparer<AIAction>
{
    public int Compare(AIAction x, AIAction y)
    {
        // Orden descendente: mayor prioridad primero
        int cmp = y.priority.CompareTo(x.priority);
        if (cmp != 0) return cmp;
        // Desempate por ID para que SortedSet no descarte duplicados de prioridad
        return x.Id.CompareTo(y.Id);
    }
}

// AIScheduler.cs — SortedSet mantiene el orden en cada inserción
using System.Collections.Generic;
using UnityEngine;

public class AIScheduler : MonoBehaviour
{
    public static AIScheduler Instance;

    // SortedSet usa un Red-Black Tree internamente:
    // Insert: O(log n), acceso al máximo: O(log n) o O(1) con .Min
    private SortedSet<AIAction> _actions
        = new SortedSet<AIAction>(new AIActionComparer());

    private void Awake() => Instance = this;

    public void ScheduleAction(AIAction action)
    {
        _actions.Add(action); // O(log n) — inserta en posición correcta
    }

    // O(1) — el primer elemento del SortedSet es siempre el de mayor prioridad
    public AIAction GetHighestPriority()
    {
        if (_actions.Count == 0) return null;
        return _actions.Min; // Min según el Comparer = mayor prioridad real
    }

    public AIAction PopHighestPriority()
    {
        if (_actions.Count == 0) return null;
        AIAction top = _actions.Min;
        _actions.Remove(top); // O(log n)
        return top;
    }

    public void RemoveAction(AIAction action)
    {
        _actions.Remove(action); // O(log n)
    }
}
